  ],
  "claims": [
    {
      "claim": "Structurally related heteroaryl-aniline/aminopyrimidine contexts report human absolute oral bioavailability at or above the F=20% threshold: GSK1322322 57% fasted/77% fed, R406 54.6%, ZL-2201 ~70% predicted, brepocitinib 75%, deucravacitinib 99%, and nilotinib 31% fasted.",
      "card_ids": ["C08","C13","C07","C10","C12","C14","C05"]
    },
    {
      "claim": "Additional L2 records reinforce the positive direction: ZL-2201 F was 115% in monkeys and 134% in mice, phenserine rat F was 100%, brepocitinib is described as orally bioavailable with dose-dependent exposure, and cirrhosis contexts for propranolol/isradipine remain above 20%.",
      "card_ids": ["C16","C18","C15","C19","C20","C21","C22","C23","C24"]
    },
    {
      "claim": "The lowest relevant measured F among transferable contexts is nilotinib at about 31% fasted, still above the threshold; its low value is attributed to precipitation/incomplete absorption rather than a general class liability.",
      "card_ids": ["C05","C17","C25"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for ACT-280778, batefenterol, and ramosetron show measurable oral exposure but lack IV comparators and are not query-specific; they cannot quantify F and do not alter the transfer-based assessment.",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    },
    {
      "claim": "No active record provides affirmative evidence of F < 20% for the query or for a transferable context; the unfavorable physicochemical prior is not endpoint proof.",
      "card_ids": ["C08","C13","C07","C10","C12","C14","C05","C16","C18","C15","C17","C21","C22","C23","C24"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule; prediction relies on transfer from analog contexts.",
    "L3 oral exposure records lack IV comparators and are for different molecules, so they cannot establish F for the query.",
    "No query-specific data on isopropyl ester stability/prodrug behavior, acrylamide reactivity, first-pass metabolism, solubility, or formulation.",
    "Fed/fasted and dose conditions for the query are unspecified; F can vary (e.g., GSK1322322 57% fasted vs 77% fed).",
    "Physicochemical liabilities (MW 585, logP 5.08, TPSA 114, low neutral fraction) could reduce absorption but are not affirmative threshold evidence."
  ],
  "decision_summary": "High: multiple transferable positive absolute-bioavailability contexts (31-99%) and no affirmative low-F evidence support F>=20%; L3 oral exposure records are neutral (no comparator, not query-specific), so the prior high prediction is kept with moderate confidence."
}

